'use strict';
// VS Code glue: hovers and the Run File / Show Python / Run Tests commands.
// Words come from data/keywords.json, generated by tools/gen_vscode_grammar.py.

const vscode = require('vscode');
const cp = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const lookup = require('./lib/lookup');

const LANG = 'slaython';
const TERMINAL_NAME = 'Slaython';

function loadIndex() {
  const file = path.join(__dirname, 'data', 'keywords.json');
  return lookup.buildIndex(JSON.parse(fs.readFileSync(file, 'utf8')));
}

function command() {
  return vscode.workspace.getConfiguration('slaython').get('command') || 'slaython';
}

function terminal(cwd) {
  const open = vscode.window.terminals.find((t) => t.name === TERMINAL_NAME && !t.exitStatus);
  return open || vscode.window.createTerminal({ name: TERMINAL_NAME, cwd });
}

function folderFor(uri) {
  const folder = uri && vscode.workspace.getWorkspaceFolder(uri);
  if (folder) return folder.uri.fsPath;
  const first = vscode.workspace.workspaceFolders && vscode.workspace.workspaceFolders[0];
  return first ? first.uri.fsPath : undefined;
}

// The .slay editor a command applies to: the clicked file or the active editor.
async function slayDocument(uri) {
  if (uri instanceof vscode.Uri) return vscode.workspace.openTextDocument(uri);
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === LANG) return editor.document;
  vscode.window.showWarningMessage('Open a .slay file first.');
  return undefined;
}

async function runFile(uri) {
  const doc = await slayDocument(uri);
  if (!doc) return;
  if (doc.isUntitled) {
    vscode.window.showWarningMessage('Save the file before running it.');
    return;
  }
  if (doc.isDirty && !(await doc.save())) return;
  const file = doc.uri.fsPath;
  const term = terminal(folderFor(doc.uri) || path.dirname(file));
  term.show();
  term.sendText(lookup.terminalLine(command(), [file], process.platform));
}

function runTests() {
  const editor = vscode.window.activeTextEditor;
  const folder = folderFor(editor && editor.document.uri);
  if (!folder) {
    vscode.window.showWarningMessage('Open a folder to run Slaython tests.');
    return;
  }
  const term = terminal(folder);
  term.show();
  term.sendText(lookup.terminalLine(command(), ['test', folder], process.platform));
}

function translate(file, cwd) {
  const [exe, ...pre] = lookup.splitCommand(command());
  return new Promise((resolve, reject) => {
    cp.execFile(exe, [...pre, 'translate', file], { cwd, maxBuffer: 64 * 1024 * 1024 },
      (err, stdout, stderr) => {
        if (!err) return resolve(stdout);
        if (err.code === 'ENOENT') {
          return reject(new Error(`Could not find "${exe}". Install Slaython or set slaython.command (for example "python -m slaython").`));
        }
        return reject(new Error((stderr || err.message).trim()));
      });
  });
}

async function showPython(uri) {
  const doc = await slayDocument(uri);
  if (!doc) return;
  let file = doc.uri.fsPath;
  let tmp;
  if (doc.isUntitled) {
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'slaython-'));
    file = path.join(tmp, 'untitled.slay');
    fs.writeFileSync(file, doc.getText(), 'utf8');
  } else if (doc.isDirty && !(await doc.save())) {
    return;
  }
  try {
    const python = await translate(file, folderFor(doc.uri) || path.dirname(file));
    const out = await vscode.workspace.openTextDocument({ language: 'python', content: python });
    await vscode.window.showTextDocument(out, { viewColumn: vscode.ViewColumn.Beside, preview: true });
  } catch (err) {
    vscode.window.showErrorMessage(`Slaython: ${err.message}`);
  } finally {
    if (tmp) fs.rmSync(tmp, { recursive: true, force: true });
  }
}

function activate(context) {
  const index = loadIndex();
  context.subscriptions.push(
    vscode.languages.registerHoverProvider(LANG, {
      provideHover(document, position) {
        const hit = lookup.wordAt(document.getText(), document.offsetAt(position), index);
        if (!hit) return undefined;
        const range = new vscode.Range(document.positionAt(hit.start), document.positionAt(hit.end));
        return new vscode.Hover(new vscode.MarkdownString(lookup.hoverMarkdown(hit.entry)), range);
      },
    }),
    vscode.commands.registerCommand('slaython.runFile', runFile),
    vscode.commands.registerCommand('slaython.showPython', showPython),
    vscode.commands.registerCommand('slaython.runTests', runTests),
  );
}

function deactivate() {}

module.exports = { activate, deactivate };
